edits.replacement:
body.padon #root #keysmodal::after{ content:'A  Rebind      B  Back'; }
/* v28.xx (cw-sethint2) critic c-31 round 14 (Pad buttons 74 at 2: "the Esc Close hint is about 14px"; "the fade clips the Gear row mid-glyph"; "a 3-line label is crammed against the row above"). Now: the hint is 20px, the list fade is 24px instead of 32 (with 24px of padding under the last row), and a pad row has 8px of air above and below its label. */
#root #settingsmodal::after, #root #keysmodal::after{ font-size:var(--fs-body); }
#root #keyslist, #root #setlist{ padding-bottom:var(--sp-3); -webkit-mask-image:linear-gradient(to bottom, var(--ui-void) calc(100% - var(--sp-3)), transparent); mask-image:linear-gradient(to bottom, var(--ui-void) calc(100% - var(--sp-3)), transparent); }
#root #keyslist .row{ padding-block:var(--sp-1); }

check:
{v:'VER',what:'the Settings key-hint line is 20px and the list fade is 24px',
 run:function(){
   var bad=[], m, fs, mk, l, padWas=document.body.classList.contains('padon');
   __runPrep(); __topClear(); __resetCfg(); __pinDefaults(0); __cleanProfile();
   try{
     document.body.classList.remove('padon');
     openSettings('display');
     m=document.getElementById('settingsmodal');
     if(!m) bad.push('no settings modal');
     else{
       fs=parseFloat(getComputedStyle(m,'::after').fontSize);
       if(!(fs>=19.5)) bad.push('the key hint is '+fs+'px');
       l=document.getElementById('setlist');
       mk=l?(getComputedStyle(l).webkitMaskImage||getComputedStyle(l).maskImage||''):'';
       if(mk.indexOf('calc(100% - 24px)')<0 && mk.indexOf('calc(100% - 24')<0) bad.push('the list fade is not 24px: '+mk.slice(0,160));
     }
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ var q=document.getElementById('settingsmodal'); if(q) q.classList.remove('on'); }catch(_k){} try{ __topClear(); }catch(_c){} document.body.classList.toggle('padon',padWas); }
   return bad.length?bad.join('; '):null; }},
